-- robinhood-stock-tokens ClickHouse schema. Inserts only - ReplacingMergeTree dedupes on
-- the ORDER BY key so a re-sunk block is idempotent.
--
-- Decimal columns: substreams-sink-sql (DatabaseChanges mode) cannot insert
-- into ClickHouse Decimal columns directly, so each exact value arrives as a
-- `<name>_str String` and `<name> Decimal(38,18)` is MATERIALIZED from it.
-- The sink skips MATERIALIZED columns on insert - query the Decimal column.

CREATE TABLE IF NOT EXISTS stock_swaps (
    tx_hash             String,
    log_index           UInt32,
    block_num           UInt64,
    block_ts            UInt64,
    block_time          DateTime,
    pool_id             String,
    ticker              LowCardinality(String),
    token               String,
    side                LowCardinality(String),
    shares_ui_str           String,
    shares_raw_adjusted_str String,
    quote_amount_str        String,
    amount_usd_str          String,
    price_usd_str           String,
    shares_ui           Decimal(38, 18) MATERIALIZED toDecimal128OrNull(shares_ui_str, 18),
    shares_raw_adjusted Decimal(38, 18) MATERIALIZED toDecimal128OrNull(shares_raw_adjusted_str, 18),
    quote_amount        Decimal(38, 18) MATERIALIZED toDecimal128OrNull(quote_amount_str, 18),
    amount_usd          Decimal(38, 18) MATERIALIZED toDecimal128OrNull(amount_usd_str, 18),
    price_usd           Decimal(38, 18) MATERIALIZED toDecimal128OrNull(price_usd_str, 18),
    quote_symbol        LowCardinality(String),
    quote_kind          LowCardinality(String),
    priced              Bool,
    shares_known        Bool,
    sender              String,
    origin              String,
    fee                 UInt32,
    hook_address        String
) ENGINE = ReplacingMergeTree
ORDER BY (ticker, block_time, tx_hash, log_index);

CREATE TABLE IF NOT EXISTS chainlink_answers (
    tx_hash        String,
    log_index      UInt32,
    block_num      UInt64,
    block_ts       UInt64,
    block_time     DateTime,
    ticker         LowCardinality(String),
    feed           String,
    aggregator     String,
    answer_usd_str String,
    answer_usd     Decimal(38, 18) MATERIALIZED toDecimal128OrNull(answer_usd_str, 18),
    round_id       UInt64,
    updated_at     DateTime
) ENGINE = ReplacingMergeTree
ORDER BY (ticker, block_time, tx_hash, log_index);

CREATE TABLE IF NOT EXISTS basis_ticks (
    tx_hash         String,
    log_index       UInt32,
    block_num       UInt64,
    block_ts        UInt64,
    block_time      DateTime,
    ticker          LowCardinality(String),
    implied_usd_str String,
    ref_usd_str     String,
    amount_usd_str  String,
    implied_usd     Decimal(38, 18) MATERIALIZED toDecimal128OrNull(implied_usd_str, 18),
    ref_usd         Decimal(38, 18) MATERIALIZED toDecimal128OrNull(ref_usd_str, 18),
    amount_usd      Decimal(38, 18) MATERIALIZED toDecimal128OrNull(amount_usd_str, 18),
    ref_source      LowCardinality(String),
    ref_ts          DateTime,
    premium_bps     Int64,
    session         LowCardinality(String),
    side            LowCardinality(String)
) ENGINE = ReplacingMergeTree
ORDER BY (ticker, block_time, tx_hash, log_index);

CREATE TABLE IF NOT EXISTS stock_registry (
    ticker         LowCardinality(String),
    token          String,
    feed           String,
    aggregator     String,
    multiplier_str String,
    multiplier     Decimal(38, 18) MATERIALIZED toDecimal128OrNull(multiplier_str, 18),
    decimals       UInt32,
    status         LowCardinality(String),
    name           String,
    has_feed       Bool,
    snapshot_date  Date
) ENGINE = ReplacingMergeTree
ORDER BY token;

-- Generated by scripts/gen-registry-sql.sh from data/registry-4663.tsv
-- joined with data/feed-token-map.tsv. Regenerate the script's output
-- rather than hand-editing the rows between the markers below.
-- BEGIN GENERATED STOCK_REGISTRY ROWS
-- END GENERATED STOCK_REGISTRY ROWS

-- stock_swaps, chainlink_answers and basis_ticks are ReplacingMergeTree, so
-- a reader must query them with FINAL to dedupe on the ORDER BY key - the
-- *_v views below always do. They are plain views, not materialized: every
-- query recomputes straight from FINAL, so they stay correct across a
-- cursor replay (a re-sunk block just replaces the row it dedupes
-- against, rather than double-counting into a stored partial state).
-- This sink has no reorg handling in ClickHouse, so replaying from an
-- earlier cursor is the recovery path after a reorg, and these views
-- depend on that replay being safe.

CREATE VIEW IF NOT EXISTS basis_hourly_v AS
SELECT
    ticker,
    toStartOfHour(block_time)                                            AS hour,
    ref_source,
    avg(premium_bps)                                                     AS avg_premium_bps,
    min(premium_bps)                                                     AS min_premium_bps,
    max(premium_bps)                                                     AS max_premium_bps,
    argMax(toDecimal128OrZero(implied_usd_str, 18), (block_num, log_index)) AS last_implied_usd,
    argMax(toDecimal128OrZero(ref_usd_str, 18), (block_num, log_index))     AS last_ref_usd,
    count()                                                               AS swap_count,
    sum(toDecimal128OrZero(amount_usd_str, 18))                          AS volume_usd
FROM basis_ticks FINAL
GROUP BY ticker, hour, ref_source;

CREATE VIEW IF NOT EXISTS swaps_hourly_v AS
SELECT
    ticker,
    toStartOfHour(block_time)                                  AS hour,
    countIf(side = 'buy')                                      AS buys,
    countIf(side = 'sell')                                     AS sells,
    sum(toDecimal128OrZero(amount_usd_str, 18))                AS volume_usd,
    sumIf(toDecimal128OrZero(shares_ui_str, 18), shares_known) AS shares
FROM stock_swaps FINAL
GROUP BY ticker, hour;
